suppressMessages(library(data.table)); options(width = 200); x <- readRDS("experiments/absolute/_out/run.rds"); F <- x$fantasia; E <- x$exercise
AGE <- c(young = 27.5, older = 76.5); ihr <- function(age) (118.1 - 0.57 * age)   # bpm, Jose & Collison; group midpoints of the Fantasia age ranges
F[, `:=`(sd_s = sqrt(sig2), sd_p = sqrt(lp * sig2), hr = 60 * rate, tau_p = 1 / kp, tau_s = 1 / ks)]; F[, ihr := ihr(AGE[group])]; F[, delta := hr - ihr]   # delta: net tone in bpm (negative: vagal dominance)
icc1 <- function(y, g) { g <- factor(g); k <- table(g); k0 <- (sum(k) - sum(k^2) / sum(k)) / (nlevels(g) - 1); m <- tapply(y, g, mean); msb <- sum(k * (m - mean(y))^2) / (nlevels(g) - 1); msw <- sum((y - m[as.character(g)])^2) / (length(y) - nlevels(g)); (msb - msw) / (msb + (k0 - 1) * msw) }
W <- F[window > 0]; cat("\n1. Stability across four 30-minute windows of resting recordings (ICC, 40 people)\n"); print(rbindlist(lapply(c("hr", "sd_p", "sd_s", "tau_p", "tau_s", "lp"), function(v) data.table(index = v, icc = round(icc1(W[[v]], W$id), 2), icc_log = round(icc1(log(W[[v]]), W$id), 2)))))
G <- F[window == 0]; auc <- function(a, b) mean(outer(a, b, ">")) + 0.5 * mean(outer(a, b, "=="))
cat("\n2. Young vs older (whole record): median, Cohen's d (older - young) and AUC (young > older)\n")
print(rbindlist(lapply(c("hr", "sd_p", "sd_s", "tau_p", "tau_s", "lp", "delta"), function(v) { a <- G[group == "young"][[v]]; b <- G[group == "older"][[v]]; data.table(index = v, young = round(median(a), 3), older = round(median(b), 3), d = round((mean(b) - mean(a)) / sqrt((var(a) + var(b)) / 2), 2), auc_young_higher = round(auc(a, b), 2)) })))
cat("\n3. Closure: net tone from variability. Delta (Hz) = beta_s * SD_s - beta_p * SD_p, mu_p = beta_p SD_p, mu_s = beta_s SD_s (no intercept)\n"); G[, delta_hz := delta / 60]
fit2 <- lm(delta_hz ~ 0 + sd_s + I(-sd_p), data = G); print(summary(fit2)$coefficients); cat("R2 (uncentred) =", round(summary(fit2)$r.squared, 3), " cor(SD_s, SD_p) =", round(cor(G$sd_s, G$sd_p), 3), "\n")
G[, d_sd := sd_s - sd_p]; fit1 <- lm(delta_hz ~ 0 + d_sd, data = G); a <- coef(fit1)[["d_sd"]]; cat("common CV: 1/c =", round(a, 2), " c =", round(1 / a, 4), "  per group: ", paste(sapply(c("young", "older"), function(g) { z <- lm(delta_hz ~ 0 + d_sd, data = G[group == g]); paste0(g, " c=", round(1 / coef(z)[[1]], 4)) }), collapse = "; "), "\n")
G[, `:=`(mu_p = a * sd_p, mu_s = a * sd_s)]; G[, ihr_hz := ihr / 60]   # common-CV closure (the two-coefficient version is not identified, see above)
cat("\nWithin-group check (does the closure explain person-to-person differences in net tone beyond the group mean?)\n"); print(G[, .(n = .N, cor_pred_obs = round(cor(predict(fit2, .SD), delta_hz), 2)), by = group])
cat("\nImplied intrinsic rate in Fantasia (rate + mu_p - mu_s, bpm; formula value in brackets is the group's):\n"); print(G[, .(implied_ihr = round(median(60 * (rate + mu_p - mu_s))), formula_ihr = round(median(ihr)), mu_p_bpm = round(60 * median(mu_p)), mu_s_bpm = round(60 * median(mu_s))), by = group]); cat("\nImplied levels (common-CV closure, c from the whole Fantasia sample), medians in bpm: vagal tone mu_p, sympathetic tone mu_s; share with mu_p, mu_s > 0 and mu_p <= IHR\n"); print(G[, .(mu_p_bpm = round(60 * median(mu_p), 1), mu_s_bpm = round(60 * median(mu_s), 1), pos = round(100 * mean(mu_p > 0 & mu_s > 0)), mu_p_le_ihr = round(100 * mean(mu_p <= ihr_hz))), by = group])
cat("\n4. Exercise: implied intrinsic rate (rest rate + mu_p - mu_s, bpm) and coherence of the vagal withdrawal (|change| <= resting vagal tone)\n"); E[, `:=`(sd_s = sqrt(sig2), sd_p = sqrt(lp * sig2))]; E[, `:=`(mu_p = a * sd_p, mu_s = a * sd_s)]
E[, `:=`(ihr_implied = 60 * (rest_rate + mu_p - mu_s), withdrawal_ratio = -d_vagal / mu_p)]; print(E[, .(n = .N, ihr_implied_median = round(median(ihr_implied)), q10 = round(quantile(ihr_implied, .1)), q90 = round(quantile(ihr_implied, .9)), plausible_70_125 = round(100 * mean(ihr_implied > 70 & ihr_implied < 125)), withdrawal_over_tone_median = round(median(withdrawal_ratio), 2), violating_pct = round(100 * mean(withdrawal_ratio > 1)))])
cat("\nGroup-level sanity for the exercise cohort (rest HR, bpm):", round(60 * median(E$rest_rate)), "\n"); fwrite(rbind(G[, .(ds = "fantasia", id, group, hr, delta, mu_p_bpm = 60 * mu_p, mu_s_bpm = 60 * mu_s)], E[, .(ds = "exercise", id, group = NA_character_, hr = 60 * rest_rate, delta = NA_real_, mu_p_bpm = 60 * mu_p, mu_s_bpm = 60 * mu_s)]), "experiments/absolute/_out/levels.csv")
